scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsGlideRecord(ast).rowCounts();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-GR-006',
        title: 'getRowCount() used to count records',
        recommendation: 'Count with GlideAggregate (addAggregate(\'COUNT\') and getAggregate(\'COUNT\')), which counts in the database instead of loading every row.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
